<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AutoCare / Sistem Informasi Kendaraan</title><style>:root{--acid:#c9ff57;--ink:#080b10;--rule:#2a3443;--copy:#f0f4fa;--muted:#91a0b5}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--copy);font-family:Arial,Helvetica,sans-serif}.intro{min-height:100vh;display:grid;grid-template-columns:1fr 260px;position:relative;overflow:hidden;background:radial-gradient(circle at 62% 38%,#1b3151 0,transparent 24%),#080b10}.intro:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0,transparent 4px,#ffffff05 5px);pointer-events:none}.intro:after{content:'AUTO\A CARE';white-space:pre;position:absolute;right:-1vw;bottom:-4vw;font:900 clamp(105px,19vw,320px)/.68 Arial;color:#ffffff06;letter-spacing:-.12em}.intro-main{z-index:1;padding:32px 6vw;display:flex;flex-direction:column;justify-content:space-between}.brand{font:800 18px Arial;letter-spacing:-.8px}.brand b{color:var(--acid)}.kicker{color:var(--acid);font:700 11px monospace;letter-spacing:.14em}.headline{margin:8vh 0 0;font-size:clamp(60px,11vw,160px);line-height:.76;letter-spacing:-.095em;text-transform:uppercase;animation:reveal .9s both}.desc{max-width:430px;color:#bcc8d8;font-size:15px;margin-top:28px;animation:up .7s .25s both}.enter{display:inline-flex;margin-top:34px;padding:14px 17px;background:var(--acid);color:#101609;text-decoration:none;font:800 11px monospace;letter-spacing:.08em;width:max-content;animation:up .7s .4s both}.enter:hover{background:#e0ff99}.side{z-index:1;border-left:1px solid var(--rule);padding:30px 22px;display:flex;flex-direction:column;justify-content:space-between;color:var(--muted);font:11px/1.7 monospace}.side b{font-size:50px;line-height:1;color:#fff;letter-spacing:-.1em}.pulse{display:inline-block;width:7px;height:7px;background:var(--acid);box-shadow:0 0 12px var(--acid);margin-right:7px;animation:pulse 1.5s infinite}@keyframes reveal{from{opacity:0;transform:translateY(32px);clip-path:inset(0 0 100% 0)}to{opacity:1;transform:none;clip-path:inset(0)}}@keyframes up{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}@keyframes pulse{50%{opacity:.35}}@media(max-width:700px){.intro{grid-template-columns:1fr}.intro-main{padding:27px}.headline{font-size:74px;margin-top:13vh}.side{border-left:0;border-top:1px solid var(--rule);min-height:110px;flex-direction:row}.side div:last-child{display:none}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}</style></head><body><main class="intro"><section class="intro-main"><div class="brand">AUTO<b>CARE</b> / SIS.INFO</div><div><div class="kicker"><span class="pulse"></span>SYSTEM INTRODUCTION / 01</div><h1 class="headline">Rawat.<br>Catat.<br>Terkendali.</h1><p class="desc">Sistem informasi untuk mencatat kendaraan, membaca riwayat perawatan, dan memantau jadwal servis dengan lebih pasti.</p><a class="enter" href="{{ route('login') }}">MASUK KE SISTEM →</a></div><div class="kicker">VEHICLE INFORMATION SYSTEM / EST.2026</div></section><aside class="side"><div>01 / INTRO<br>02 / AUTHENTICATION<br>03 / OPERATION CONTROL</div><div><b>AC</b><br>STATUS: ONLINE</div><div>DATA FIRST.<br>MAINTENANCE READY.</div></aside></main></body></html>
